<?php if ($d['isEdit'] && $t): ?><script>
(function(){
  var b = document.getElementById('mt-body'), pv = document.getElementById('mt-pv'), cnt = document.getElementById('mt-count'), sms = <?= json_encode($tab === 'sms') ?>, S = <?= json_encode($d['sample'], JSON_HEX_TAG) ?>, site = <?= json_encode($site) ?>;
  function fill(t){ return t.replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/\[USERNAME\]|\[NAME\]/g, S.name).replace(/\[SITE_NAME\]/g, site).replace(/\[TRACKING_NUMBER\]|\[TRACK\]/g, 'SL-100480').replace(/\[STATUS\]/g, 'Ready for pickup').replace(/\[URL_SHIP\]|\[URL\]|\[LINK\]/g, location.origin); }
  function up(){ pv.textContent = fill(b.value); var n = b.value.length; cnt.textContent = sms ? n + ' characters · ' + Math.max(1, Math.ceil(n / 153)) + ' SMS part' + (n > 153 ? 's' : '') : n + ' characters'; }
  b.addEventListener('input', up);
  document.addEventListener('click', function(e){ var v = e.target.closest('[data-mt-var]'); if (v) { var s = b.selectionStart || b.value.length; b.value = b.value.slice(0, s) + v.getAttribute('data-mt-var') + b.value.slice(s); up(); } });
  var tb = document.getElementById('mt-test'); if (tb) tb.addEventListener('click', function(){ var f = document.getElementById('mt-form'), fd = new FormData(f); fd.set('op', 'test'); SL.post('<?= $ajax ?>', fd).then(function(j){ SL.toast(j.message || '', !j.success); }); });
})();
</script><?php endif; ?>
